namespace ghidra.framework.options;





using ghidra.util;
using ghidra.util;
using utilities.util.reflection;

public abstract class Option {

	public static readonly string UNREGISTERED_OPTION = "Unregistered Option";

	private static readonly LocalDate ONE_YEAR_AGO = LocalDate.now().minusYears(1);

	private string name;
	private object defaultValue;
	private bool isRegistered;
	private LocalDate lastRegisteredDate;
	private string description;
	private HelpLocation helpLocation;
	private OptionType optionType;

	private PropertyEditor propertyEditor;
	private string inceptionInformation;

	protected Option(string name, OptionType optionType, string description,
			HelpLocation helpLocation, object defaultValue, bool isRegistered,
			PropertyEditor editor) {
		this.name = name;
		this.optionType = optionType;
		this.description = description;
		this.helpLocation = helpLocation;
		this.defaultValue = defaultValue;
		this.isRegistered = isRegistered;
		this.propertyEditor = editor;
		if (isRegistered) {
			lastRegisteredDate = LocalDate.now();
		}
		else {
			recordInception();
		}
	}

	/**
	 * Update any null registration information using the specified updated information.
	 * This assumption is that multiple registrations for the same option may be partial
	 * but will be compatible.  No compatibility checks are performed between existing
	 * registration and update registration info.
	 * @param updatedDescription updated option description (will be ignored if description previously set)
	 * @param updatedHelp updated option help location (will be ignored if help location previously set)
	 * @param updatedDefaultValue updated option default-value (will be ignored if default-value previously set)
	 * @param updatedEditor updated option editor (will be ignored if editor previously set)
	 */
	void updateRegistration(string updatedDescription, HelpLocation updatedHelp,
			object updatedDefaultValue, PropertyEditor updatedEditor) {
		description = description != null ? description : updatedDescription;
		helpLocation = helpLocation != null ? helpLocation : updatedHelp;
		defaultValue = defaultValue != null ? defaultValue : updatedDefaultValue;
		propertyEditor = propertyEditor != null ? propertyEditor : updatedEditor;
		isRegistered = true;
		lastRegisteredDate = LocalDate.now();
	}

	public abstract object getCurrentValue();

	public abstract void doSetCurrentValue(object value);

	public void setCurrentValue(object value) {
		isRegistered = true;
		lastRegisteredDate = LocalDate.now();
		doSetCurrentValue(value);
	}

	public string getName() {
		return name;
	}

	public PropertyEditor getPropertyEditor() {
		return propertyEditor;
	}

	public HelpLocation getHelpLocation() {
		return helpLocation;
	}

	public string getDescription() {
		// 'Unregistered Option' is returned when an option was never registered.  It can also be
		// returned when an option value was set, but the option itself was never registered.  In 
		// that case, the isRegistered value is set to true, which means that a client has accessed
		// the option.  
		return description == null ? UNREGISTERED_OPTION : description;
	}

	public object getValue(object passedInDefaultValue) {
		object value = getCurrentValue();
		if (value == null && defaultValue == null) {
			// Assume that both values being null is an indication that there is no value
			// to use.  Otherwise, a null current value implies that the user has cleared
			// the default value.
			return passedInDefaultValue;
		}
		return value;
	}

	public bool wasRegisteredInPreviousSession() {
		return lastRegisteredDate != null;
	}

	public bool isRegistered() {
		return isRegistered;
	}

	public void setLastRegisteredDate(LocalDate date) {
		lastRegisteredDate = date;
	}

	public LocalDate getLastRegisteredDate() {
		LocalDate date = lastRegisteredDate;
		if (date == null) {
			// This implies a new option that has not been registered and was not in a saved tool.
			// Pick an old date so the option will not linger.
			date = ONE_YEAR_AGO;
		}
		return date;
	}

	/**
	 * Returns true if the last registered date for this option is older than 1 year ago.  That 
	 * means that the option has not been registered and is likely no longer valid. This may not be
	 * true, if the given option still exists, but is only active on-demand by the user.   If the
	 * option has expired, it will be removed.  If it is still an existing on-demand option, it can
	 * again be saved when the user loads the owning provider and changes the option.  In this case, 
	 * it will remain in the tool for at least another year.
	 * @return true if expired
	 */
	public bool hasExpired() {
		if (lastRegisteredDate == null) {
			return false;
		}
		return lastRegisteredDate.isBefore(ONE_YEAR_AGO);
	}

	public void restoreDefault() {
		setCurrentValue(defaultValue);
	}

	public bool isDefault() {
		object value = getCurrentValue();
		return Objects.equals(value, defaultValue);
	}

	/* @Override */
	public string toString() {
		return "[current value=" + getCurrentValue() + ", default value=" + defaultValue +
			", isRegistered=" + isRegistered + "]";
	}

	public object getDefaultValue() {
		return defaultValue;
	}

	public string getInceptionInformation() {
		return inceptionInformation;
	}

	private void recordInception() {
		if (!SystemUtilities.isInDevelopmentMode()) {
			return;
		}
		Throwable throwable = new Throwable();
		StackTraceElement[] stackTrace = throwable.getStackTrace();

		StackTraceElement[] filteredTrace =
			ReflectionUtilities.filterStackTrace(stackTrace, "option", "OptionsManager");
		inceptionInformation = filteredTrace[0].toString();
	}

	public OptionType getOptionType() {
		return optionType;
	}

}
